        parts = re.split(r'\n\n(?=\d{4}-\d\d-\d\d \d\d:\d\d:\d\d )', t)
        for n, blk in enumerate(parts[1:], 1):
            blk = blk.rstrip('\n')
            lines = blk.split('\n')
            m = re.match(r'(\d{4}-\d\d-\d\d \d\d:\d\d:\d\d) (.*)$', lines[0])
            ts = datetime.strptime(m.group(1), '%Y-%m-%d %H:%M:%S').replace(tzinfo=NY)
