            note('etd_after_shipped', f'{doc.url}: {po} etd {d} ignored, PO already {p.status}'); return
        p.etd = d; p.etd_doc = doc.issued
        facts.append({'e': ['po/number', po], 'a': 'po/etd', 'v': d.isoformat()})

